import random
import torch
import time
import numpy as np
import torch.nn as nn


# base class for proceesing the birth-and-death transition probabilities generated by neural networks
class BDTP(nn.Module):
    def __init__(self, n_states, n_actions, n_neighbors):
        super().__init__()
        self.n_states = n_states
        self.n_actions = n_actions
        self.n_neigbors = n_neighbors
        # calculate nnz in each row
        base = torch.arange(n_states).unsqueeze(1)  # (n_states, 1)
        offsets = torch.arange(-n_neighbors, n_neighbors + 1).unsqueeze(0)  # (1, 2*n_neighbors + 1)
        neighbors = base + offsets  # (n_states, 2*n_neighbors + 1)
        valid_mask = (neighbors > 0) & (neighbors < n_states)  # shape (n_states, 2*n_neighbors + 1)
        true_col = torch.ones(n_states, 1, dtype=torch.bool)
        final_mask = torch.cat([true_col, valid_mask], dim=1)  # (n_states, 2*n_neighbors + 2)
        row_sizes = final_mask.sum(dim=1)

        # create a mask to indicate which elements produced by neural networks should be in the transition probs
        nn_mask = torch.arange(row_sizes.max().item()).unsqueeze(0) < row_sizes.unsqueeze(1)
        self.register_buffer('mask', nn_mask)  # (n, max nnz_per_row), bool, part of the model, but not learnable

    def process_logits(self, logits):
        """
        Shared post-processing: masked softmax for each row of the transition probability

        Args:
            logits: (n_samples, n_states, max nnz_per_row, n_actions)

        Returns:
            probs_flat: (n_samples, nnz, n_actions)
        """

        mask = self.mask.unsqueeze(0).unsqueeze(-1)  # (1, n_states, max nnz_per_row, 1)
        masked_logits = logits.masked_fill(~mask, float('-inf'))
        # apply softmax to each row of the transition probability
        probs_full = nn.functional.softmax(masked_logits, dim=2)
        mask_flat = self.mask.view(-1)
        # filter the nonzero probs and save them in a flat array for each sample and each action
        probs = probs_full.reshape(logits.shape[0], -1, self.n_actions)[:, mask_flat, :]

        return probs


class GroundTruth(BDTP):
    def __init__(self, input_dim, n_states, n_actions, n_neighbors):
        super().__init__(n_states, n_actions, n_neighbors)
        self.model = nn.Sequential(
            nn.Linear(input_dim, 512),
            nn.ReLU(),
            nn.Linear(512, 256),
            nn.ReLU(),
            nn.Linear(256, 128),
            nn.ReLU(),
            nn.Linear(128, n_states * (2 * n_neighbors + 2) * n_actions)  # max nnz_per_row = 2 * n_neighbors + 2
        )

    def forward(self, x):
        logits = self.model(x).view(x.shape[0], self.n_states, 2 * self.n_neigbors + 2, self.n_actions)
        return self.process_logits(logits)


class ThetaPredictor(BDTP):
    def __init__(self, input_dim, hidden_dim, n_states, n_actions, n_neighbors):
        super().__init__(n_states, n_actions, n_neighbors)
        self.model = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, n_states * (2 * n_neighbors + 2) * n_actions)  # max nnz_per_row = 2 * n_neighbors + 2
        )

    def forward(self, x):
        logits = self.model(x).view(x.shape[0], self.n_states, 2 * self.n_neigbors + 2, self.n_actions)
        return self.process_logits(logits)


def set_seed(seed):
    # Set Python built-in random seed
    random.seed(seed)

    # Set NumPy seed
    np.random.seed(seed)

    # Set PyTorch seed
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)

    # Ensure deterministic behavior (PyTorch only)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


